def bounded_process(argv, *, payload=b"", timeout=10, limit=OUTPUT_BYTES):
    # The old process-group cleanup and input/wall bounds are reused verbatim.
    return isolation.bounded_process(argv, payload=payload, timeout=timeout, limit=limit)


BUNDLE_TEMPLATE = r'''import base64,hashlib,sys,time,types,zlib
started=time.monotonic()
def need(ok):
 if not ok:raise RuntimeError('reviewed_bundle_invalid')
pins=@PINS@
records=@RECORDS@
need(type(records) is tuple and tuple(r[0] for r in records)==tuple(pins))
compressed_total=source_total=0
verified=[]
for name,size,sha,csize,csha,data in records:
 need(type(size) is int and 0<size<=131072 and type(csize) is int and 0<csize<=49152)
 need(type(data) is str and len(data)<=65536 and sha==pins[name])
 compressed=base64.b64decode(data,validate=True)
 need(len(compressed)==csize and hashlib.sha256(compressed).hexdigest()==csha)
 compressed_total+=csize;source_total+=size
 need(compressed_total<=65536 and source_total<=196608)
 decoder=zlib.decompressobj();source=decoder.decompress(compressed,size+1)
 need(len(source)==size and decoder.eof and not decoder.unused_data and not decoder.unconsumed_tail)
 need(hashlib.sha256(source).hexdigest()==sha)
 verified.append((name,source))
for name,source in verified:
 if name=='ibm_school_worlds':
  namespace={'__name__':'__main__','__bundle_started_monotonic__':started}
 else:
  module=types.ModuleType(name);sys.modules[name]=module;namespace=module.__dict__
 exec(compile(source,name,'exec'),namespace)
'''


def bundled_host_source(*, root=None):
    root = Path(__file__).resolve().parents[1] if root is None else Path(root)
    need(type(SOURCE_RECORDS) is tuple and tuple(row[0] for row in SOURCE_RECORDS) == tuple(SOURCE_PINS), "bundle_records")
    compressed_total = source_total = 0
    for name, size, sha, csize, csha, data in SOURCE_RECORDS:
        path = MODULE_PATHS[name]
        source = (root / path).read_bytes()
        need(0 < len(source) <= MODULE_BYTES and hashlib.sha256(source).hexdigest() == SOURCE_PINS[name], "source_pin")
        need(type(size) is int and len(source) == size and sha == SOURCE_PINS[name]
             and type(csize) is int and 0 < csize <= MODULE_COMPRESSED_BYTES
             and type(data) is str and len(data) <= 65536, "bundle_records")
        compressed = base64.b64decode(data, validate=True)
        need(len(compressed) == csize and hashlib.sha256(compressed).hexdigest() == csha, "bundle_compressed_pin")
        decoder = zlib.decompressobj()
        unpacked = decoder.decompress(compressed, size+1)
        need(unpacked == source and decoder.eof and not decoder.unused_data and not decoder.unconsumed_tail, "bundle_source_pin")
        compressed_total += len(compressed)
        source_total += len(source)
        need(compressed_total <= BUNDLE_COMPRESSED_BYTES and source_total <= BUNDLE_BYTES, "bundle_limit")
    source = BUNDLE_TEMPLATE.replace("@PINS@", repr(SOURCE_PINS)).replace("@RECORDS@", repr(SOURCE_RECORDS))
    need(hashlib.sha256(source.encode()).hexdigest() == HOST_SOURCE_SHA, "bundle_source_pin")
    return source


